import {
  Chart as ChartJS,
  LineElement,
  CategoryScale,
  LinearScale,
  PointElement,
  Tooltip,
} from "chart.js";
import { Line } from "react-chartjs-2";

ChartJS.register(LineElement, CategoryScale, LinearScale, PointElement, Tooltip);

export default function ProgressChart({ completedDays }) {
  const days = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];

  const data = {
    labels: days,
    datasets: [
      {
        label: "Tasks Completed",
        data: days.map((_, i) =>
          completedDays.includes(i + 1) ? 4 : 0
        ),
        tension: 0.4,
      },
    ],
  };

  return (
    <div className="h-64">
      <Line data={data} />
    </div>
  );
}
